cat > .local/seven-smart-2026-10-20/mcp-call.mjs <<'EOF'
import {readFile,writeFile} from 'node:fs/promises';
import {randomUUID} from 'node:crypto';
const root='.local/seven-smart-2026-10-20';
const sessionRpc=JSON.parse(await readFile(`${root}/mcp-responses/002-session.json`,'utf8'));
const unwrap=r=>r.structuredContent??JSON.parse(r.content.find(x=>x.type==='text').text);
const session=unwrap(sessionRpc.result).result.data.session;
export async function rpc(name,args){const id=`request-${randomUUID()}.json`;
 await writeFile(`${root}/mcp-requests/${id}`,JSON.stringify({method:'tools/call',params:{name,arguments:args}}),{mode:0o600});
 for(let i=0;i<400;i++){try{const r=JSON.parse(await readFile(`${root}/mcp-responses/${id}`,'utf8'));if(r.error)throw Error(JSON.stringify(r.error));const q=unwrap(r.result);if(r.result.isError||q.error)throw Error(JSON.stringify(q));return q;}catch(e){if(e.code!=='ENOENT')throw e;}await new Promise(r=>setTimeout(r,200));}throw Error('MCP response timeout');
}
export async function browserTool(toolName,args={},extra={}){const r=await rpc('opencut.classic.tool.invoke',{projectId:session.projectId,browserSessionId:session.sessionId,toolName,arguments:args,...extra});return r.result.data.output;}
if(process.argv[2])console.log(JSON.stringify(await browserTool(process.argv[2],JSON.parse(process.argv[3]??'{}'))));
EOF
